// The Data Table `get` runs once per input item. Collapse the 8 upserted rows to a
// single item first so the read-back returns the table once, not eight times.
return [{ json: { seeded: $input.all().length } }];

// One document per article. Title + category + keywords are prepended to the body so
// that short, keyword-shaped questions ("SSO", "429") still land on the right article -
// pure body text alone under-retrieves for terse support tickets.
return $input.all().map((item) => {
  const a = item.json;
  const text = [
    `# ${a.title}`,
    `Category: ${a.category}`,
    `Keywords: ${a.keywords}`,
    '',
    a.content,
  ].join('\n');

  return {
    json: {
      article_id: a.article_id,
      title: a.title,
      category: a.category,
      keywords: a.keywords,
      text,
    },
  };
});

// Reported back to the caller so a cold-start rehydration is visible in the
// parent execution rather than silently succeeding.
const docs = $input.all().length;
const articles = $('Prepare KB documents').all().length;
return [{
  json: {
    indexed_chunks: docs,
    indexed_articles: articles,
    memory_key: 'acme_support_kb',
    indexed_at: new Date().toISOString(),
  },
}];
